etter-spacing:1px;\">MELIORA GYM</strong><br>\n            {{address}}{{#if phone}} · {{phone}}{{/if}}<br>\n            <a href=\"{{instagramUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Instagram {{instagramHandle}}</a>\n            &nbsp;·&nbsp; <a href=\"{{mapsUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Itinéraire</a>\n            &nbsp;·&nbsp; <a href=\"{{websiteUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Site web</a>\n            {{#if footerNote}}<p style=\"margin:14px 0 0;color:#8c8c8c;\">{{footerNote}}</p>{{/if}}\n            <p style=\"margin:14px 0 0;color:#6f6f6f;\">© {{year}} Meliora Gym — Sousse, Tunisie</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>\n"};

